SELECT * FROM x_post WHERE status IN ('GENERATING','PENDING_REVIEW','APPROVED','PUBLISHING')
ORDER BY CASE status WHEN 'PUBLISHING' THEN 0 WHEN 'GENERATING' THEN 1 WHEN 'APPROVED' THEN 2 ELSE 3 END,
    updated_at, post_key LIMIT #{limit}

mapper.update:
UPDATE x_post SET body = #{row.body}, review_note = #{row.reviewNote},
    content_version = #{row.contentVersion}, revision = #{row.revision}, status = #{row.status},
    updated_at = #{row.updatedAt}, reviewer = #{row.reviewer}, reviewed_at = #{row.reviewedAt},
    review_reason = #{row.reviewReason}, attempt_id = #{row.attemptId},
    publish_started_at = #{row.publishStartedAt}, external_post_id = #{row.postId}, last_error = #{row.lastError}
WHERE post_key = #{row.id} AND revision = #{expectedRevision}
